# Find connected components of 7s using BFS
def find_components(grid, r, c, visited):
    if r < 0 or r >= rows or c < 0 or c >= cols:
        return set()
    if grid[r][c] != 7 or (r, c) in visited:
        return set()

    component = {(r, c)}
    visited.add((r, c))

    queue = [(r, c)]
    while queue:
        cr, cc = queue.pop(0)
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = cr + dr, cc + dc
            neighbor = find_components(grid, nr, nc, visited.copy() if (nr, nc) not in component else visited)
            component.update(neighbor)
            if (nr, nc) not in visited:
                visited.add((nr, nc))
                if neighbor:
                    pass

    # Actually simpler - use BFS properly
    return component

