for r in range(rows):
    for c in range(cols):
        if input_grid[r][c] == 7 and (r, c) not in visited:
            # BFS from this cell
            component = []
            to_visit = [(r, c)]
            while to_visit:
                cr, cc = to_visit.pop()
                if (cr, cc) in component:
                    continue
                component.append((cr, cc))
                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
